arguments.command:
printf '#!/bin/sh
case "$1" in
  *sername*) echo x-access-token ;;
  *assword*) echo "$GITHUB_TOKEN" ;;
esac
' > /tmp/askpass.sh && chmod +x /tmp/askpass.sh && GIT_ASKPASS=/tmp/askpass.sh GIT_TERMINAL_PROMPT=0 git -C /tmp/friend-rachel push origin HEAD:refs/heads/friend/rachel 2>&1 | tail -5
